DROP TABLE IF EXISTS `daily_weather`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `daily_weather` (
  `id` int DEFAULT NULL,
  `State` text,
  `City` text,
  `Forecast Number` int DEFAULT NULL,
  `Date` text,
  `Main Condition` text,
  `Condition Description` text,
  `Icon` text,
  `Low Temperature` double DEFAULT NULL,
  `High Temperature` double DEFAULT NULL,
  `Humidity Percentage` int DEFAULT NULL,
  `Wind MPH` int DEFAULT NULL,
  `Wind Direction` text,
  `Rain Inches` int DEFAULT NULL,
  `Snow Inches` double DEFAULT NULL,
  `Pressure` int DEFAULT NULL,
  `Cloud Percent` int DEFAULT NULL,
  `UTC Timestamp` int DEFAULT NULL,
  `Timezone Offset` int DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

