DROP TABLE IF EXISTS `us_incarcerated_population`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `us_incarcerated_population` (
  `id` int DEFAULT NULL,
  `State or region` text,
  `Total adults in correctional facilities` int DEFAULT NULL,
  `White adults in correctional facilities` int DEFAULT NULL,
  `or AA adults in correctional facilities` int DEFAULT NULL,
  `AI and Al Native adults in correctional facilitiess` int DEFAULT NULL,
  `Asian adults in correctional facilities` int DEFAULT NULL,
  `HI and other PacIs adults in correctional facilities` int DEFAULT NULL,
  `Adults of some other race in correctional facilities` int DEFAULT NULL,
  `Adults of two or more races in correctional facilities` int DEFAULT NULL,
  `Hispanic or Latino adults in correctional facilities` int DEFAULT NULL,
  `Total US Population` int DEFAULT NULL,
  `Total US Population: White adults` int DEFAULT NULL,
  `Total US Population: Black or AA adults` int DEFAULT NULL,
  `Total US Population: AI and Alaska Native adults` int DEFAULT NULL,
  `Total US Population of Asian adults` int DEFAULT NULL,
  `Total US Population: Native HI and other PacIs adults` int DEFAULT NULL,
  `Total US Population: Some other race adults` int DEFAULT NULL,
  `Total US Population: Adults of two or more races` int DEFAULT NULL,
  `Total US Population: Hispanic or Latino adults` int DEFAULT NULL,
  `Jailing rate per 100,000 adults` double DEFAULT NULL,
  `Jailing rate per 100,000 of White adults` double DEFAULT NULL,
  `Jailing rate per 100,000 of Black or AA adults` double DEFAULT NULL,
  `Jailing rate per 100,000 of AI and Alaska Native adults` double DEFAULT NULL,
  `Jailing rate per 100,000 of Asian adults` double DEFAULT NULL,
  `Jailing rate per 100,000 of Native HI and other PacIs adults` double DEFAULT NULL,
  `Jailing rate per 100,000 of some other race adults` double DEFAULT NULL,
  `Jailing rate per 100,000 of adults of two or more races` double DEFAULT NULL,
  `Jailing rate per 100,000 of Hispanic or Latino adults` double DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
